// Generated by Claude (AI-assisted).
//
// Lets readers work the book's exercises in place.
//
// Every exercise box gets a small toolbar.  On a desktop browser, "Try it here"
// opens an editor holding the exercise's code; "Run" checks it with Lean
// running inside the browser (see lean-worker.js), with everything the
// exercise depends on supplied as context.  As the reader types, the editor
// works like Lean's own editors, on a smaller scale: Lean's messages are
// squiggled where they apply and shown on hover with the type and docstring
// of the name there, the gutter marks errors and accepted theorems, names
// are completed, and a goal view follows the cursor.  Phones and small devices cannot
// hold Lean's memory, so they get "Open in the Lean playground" instead, which
// opens live.lean-lang.org with the same self-contained file.  The "⋮" menu
// offers the playground, a download of that file, and the exercise's source on
// GitHub on every device.
//
// The book's other code blocks, its examples and the proofs it gives, get
// "Edit" and the same menu in their corner, so that a reader can change one
// and see what Lean makes of the change.  The editor checks the block in the
// context an exercise in its place would get.  A change to a block stays in
// that block: the code after it is checked against the book's version.
//
// The context for an exercise comes from `sfl-lean/data/<Chapter>.json`
// (written by scripts/web_exercises.py): the chapters it imports and the
// chapter itself up to the exercise, with theorem proofs replaced by `sorry`.
// When the reader has already solved an earlier exercise here, their solution
// replaces the `sorry` version, as it would in a downloaded .lean file worked
// from top to bottom.
//
// Settings come from the attributes of this script's tag:
//   data-runtime   base URL of lean.js, lean.wasm, lean-lib-files.json and
//                  lean-lib/
//   data-version   the runtime's build id, appended as ?v= and used to key
//                  the reader's cached library files
//   data-source    URL prefix for "view source", e.g.
//                  https://github.com/plclub/sf-in-lean/blob/main/
// A page URL with ?sfl-lean=on or ?sfl-lean=off overrides the device check.

(() => {
  'use strict';

  const script = document.currentScript;
  const here = new URL('.', script.src);
  const config = {
    runtime: new URL(script.dataset.runtime || 'runtime/', here).href,
    version: script.dataset.version || '',
    source: script.dataset.source || '',
  };

  const PLAYGROUND = 'https://live.lean-lang.org/';
  const STORE = 'sfl-lean:';

  // ── Which experience this device gets ─────────────────────────────────────

  function canRunLean() {
    const forced = new URLSearchParams(location.search).get('sfl-lean');
    if (forced === 'on') return true;
    if (forced === 'off') return false;
    const ua = navigator.userAgent;
    const mobile = navigator.userAgentData ? navigator.userAgentData.mobile
      : /Android|iPhone|iPad|iPod|Mobile/i.test(ua);
    const iPadAsMac = navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1;
    if (mobile || iPadAsMac) return false;
    // Chrome reports device memory in GiB, rounded down and capped at 8.
    if (navigator.deviceMemory && navigator.deviceMemory < 4) return false;
    return typeof WebAssembly === 'object' && 'serviceWorker' in navigator;
  }

  // ── Small helpers ─────────────────────────────────────────────────────────

  function el(tag, attrs, ...children) {
    const node = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs || {})) {
      if (k === 'class') node.className = v;
      else if (k.startsWith('on')) node.addEventListener(k.slice(2), v);
      else node.setAttribute(k, v);
    }
    for (const c of children) if (c != null) node.append(c);
    return node;
  }

  function load(key) {
    try { return localStorage.getItem(STORE + key); } catch (e) { return null; }
  }
  function save(key, value) {
    try {
      if (value == null) localStorage.removeItem(STORE + key);
      else localStorage.setItem(STORE + key, value);
    } catch (e) { /* storage unavailable; the editor still works */ }
  }

  // A short name for a text (its 32-bit FNV-1a hash), to key what is saved
  // about it.
  function hashCode(text) {
    let h = 0x811c9dc5;
    for (let i = 0; i < text.length; i++) h = Math.imul(h ^ text.charCodeAt(i), 0x01000193);
    return (h >>> 0).toString(36);
  }

  function chapterOfPage() {
    const parts = location.pathname.split('/').filter((p) => p && p !== 'index.html');
    return parts[parts.length - 1];
  }

  // ── Building the file Lean checks ─────────────────────────────────────────

  // The reader's checked solutions replace the `sorry` versions of exercises
  // that come before this one, so later exercises can use them.
  function withAnswers(skeleton, exercises, chapter, upto) {
    let out = '';
    let pos = 0;
    const end = upto === undefined ? skeleton.length : upto;
    for (const e of [...exercises].sort((a, b) => a.context - b.context)) {
      if (e.context >= end) break;
      const answer = load('solved:' + chapter + ':' + e.name);
      if (answer == null) continue;
      out += skeleton.slice(pos, e.context) + answer.trimEnd() + '\n\n';
      pos = e.contextEnd;
    }
    return out + skeleton.slice(pos, end);
  }

  function header(data) {
    return (data.isModule ? 'module\n\n' : '') + data.imports.map((l) => l + '\n').join('');
  }

  // In a module, a chapter written as an ordinary file needs its declarations
  // public, with definitions unfoldable, as they are in that chapter's own file.
  function opener(data, isModule) {
    return data.isModule && !isModule ? '@[expose] public section' : 'section';
  }

  // A command such as `open Nat in` applies to the command after it, which at
  // the end of an exercise's context is the exercise itself.  Lean checks the
  // exercise as a separate continuation of the context, where `open Nat in`
  // with nothing after it does not parse; as a plain `open Nat`, the context's
  // last command, it applies to the exercise all the same.
  function closeTrailingIn(context) {
    return context.replace(/(^|\n)([ \t]*(?:open|set_option)\b[^\n]*?)[ \t]+in\s*$/, '$1$2\n\n');
  }

  // The whole file, and the line at which the reader's code starts.  A block
  // from the text comes as an exercise does, with `block` set.
  function compose(data, exercise, code, { useAnswers, banner }) {
    const lib = data.library.map((c) => {
      const chapter = c.module.split('.').slice(1).join('.');
      const sk = useAnswers ? withAnswers(c.skeleton, c.exercises, chapter) : c.skeleton;
      return `-- ${c.module}, with proofs omitted\n${opener(data, c.isModule)}\n\n${sk}end\n\n`;
    }).join('');
    const ctx = closeTrailingIn(useAnswers
      ? withAnswers(data.skeleton, data.exercises, data.chapter, exercise.context)
      : data.skeleton.slice(0, exercise.context));
    let before = header(data) + '\n' + lib +
      `-- ${data.module}, up to this ${exercise.block ? 'code' : 'exercise'}, with proofs omitted\n` +
      `${opener(data, false)}\n\n` + ctx +
      (exercise.block ? `-- From the text: ${exercise.name}\n\n` : `-- Exercise: ${exercise.name}\n\n`);
    if (banner) {
      // Count the banner's own lines too, so the line it names is exact.
      const draft = banner(0) + before;
      const line = draft.split('\n').length;
      before = banner(line) + before;
    }
    return { text: before + code, context: before, codeLine: before.split('\n').length };
  }

  // ── What Lean reports at a position ───────────────────────────────────────

  function highlighted(text) {
    return highlight(text).flatMap((pieces, i) => [
      ...(i ? ['\n'] : []),
      ...pieces.map(([cls, t]) => (cls ? el('span', { class: 'sfl-tok-' + cls }, t) : t)),
    ]);
  }

  // A goal as the runtime reports it: an optional case name, hypotheses that
  // share a type grouped together, and the target.
  function goalCard(goal, { hyps = true } = {}) {
    return el('div', { class: 'sfl-goal' },
      goal.name ? el('div', { class: 'sfl-goal-case' }, 'case ' + goal.name) : null,
      ...(hyps ? goal.hyps : []).map((h) => el('pre', { class: 'sfl-hyp' },
        ...highlighted(h.names.join(' ') + ' : ' + h.type + (h.value != null ? ' := ' + h.value : '')))),
      el('pre', { class: hyps && goal.hyps.length ? 'sfl-target' : '' },
        el('span', { class: 'sfl-turnstile' }, '⊢ '), ...highlighted(goal.target)));
  }

  // Lean's "unsolved goals" error lists the goals left at the end of a proof.
  // It means the proof is not finished yet, which the goal view shows as
  // goals, not as a mistake.
  function isUnsolvedGoals(m) {
    return m.severity === 'error' && (m.kind === 'Tactic.unsolvedGoals' || /^unsolved goals\n/.test(m.data));
  }

  // Hover text and docstrings are Markdown.  Code blocks are highlighted,
  // inline code and *emphasis* kept, and other markup shown as written.
  function markdown(text) {
    const out = [];
    text.split(/```[a-z]*\n?([\s\S]*?)```/).forEach((part, i) => {
      if (i % 2) {
        out.push(el('pre', { class: 'sfl-md-code' }, ...highlighted(part.replace(/\n$/, ''))));
        return;
      }
      part.split(/^\s*\*\*\*\s*$/m).forEach((section, j) => {
        if (j) out.push(el('hr', {}));
        for (const para of section.split(/\n\s*\n/)) {
          if (para.trim()) out.push(el('p', {}, ...inlineMarkdown(para.trim())));
        }
      });
    });
    return out;
  }

  function inlineMarkdown(text) {
    return text.split(/(`[^`\n]+`)/).flatMap((s, i) => (i % 2
      ? [el('code', {}, s.slice(1, -1))]
      : s.replace(/\[([^\]]+)\]\([^)]+\)/g, '$1').split(/(\*[^*\s][^*\n]*\*)/)
        .map((t, j) => (j % 2 ? el('em', {}, t.slice(1, -1)) : t))));
  }

  // Lean counts columns in codepoints, JavaScript strings in UTF-16 units.
  function leanColumn(lineText, offset) {
    return Array.from(lineText.slice(0, offset)).length;
  }
  function jsOffset(lineText, column) {
    let offset = 0;
    for (let n = 0; n < column && offset < lineText.length; n++) {
      offset += lineText.codePointAt(offset) > 0xffff ? 2 : 1;
    }
    return offset;
  }

  function playgroundFile(data, exercise) {
    return compose(data, exercise, exercise.code, {
      useAnswers: false,
      banner: (line) =>
        `-- Software Foundations in Lean: ${data.chapter}, ` +
        (exercise.block ? `code from the text (${exercise.name}).\n` : `exercise ${exercise.name}.\n`) +
        `-- The ${exercise.block ? 'code' : 'exercise'} is at the end of this file, from line ${line}.  Everything\n` +
        `-- above it is the book's earlier material, with proofs omitted.\n\n`,
    }).text;
  }

  // The playground reads `codez` with lz-string's base64 decoder, the way it
  // writes its own links: trailing `=` padding dropped, and `+` percent-encoded
  // so that it is not read back as a space.
  function playgroundUrl(data, exercise) {
    const z = LZString.compressToBase64(playgroundFile(data, exercise)).replace(/=+$/, '');
    return PLAYGROUND + '#codez=' + encodeURIComponent(z);
  }

  function sourceUrl(data, exercise) {
    if (!config.source || !exercise.sourcePath) return null;
    return config.source + exercise.sourcePath + (exercise.sourceLine ? '#L' + exercise.sourceLine : '');
  }

  // ── The Lean worker, shared by every editor on the page ───────────────────

  const lean = {
    worker: null,
    state: 'idle', // idle → loading → ready | failed
    listeners: new Set(),
    pending: new Map(),
    nextId: 1,
    status: '',

    start(data) {
      if (this.worker) return;
      this.state = 'loading';
      this.setStatus('Downloading Lean…');
      this.worker = new Worker(new URL('lean-worker.js', here));
      this.worker.onmessage = (e) => this.onMessage(e.data);
      this.worker.onerror = (e) => this.fail(e.message || 'the Lean worker could not start');
      this.worker.postMessage({
        type: 'boot',
        runtimeBase: config.runtime,
        version: config.version,
        header: header(data),
        debug: new URLSearchParams(location.search).has('sfl-lean-debug'),
      });
    },

    onMessage(msg) {
      if (msg.type === 'log') {
        console.debug('[sfl-lean]', msg.text);
      } else if (msg.type === 'library_progress') {
        this.setStatus(`Downloading Lean's library: ${Math.round(100 * msg.done / msg.total)}% (${(msg.bytes / 1048576).toFixed(0)} MB)`);
      } else if (msg.type === 'importing') {
        this.setStatus('Starting Lean…');
      } else if (msg.type === 'import_progress') {
        this.setStatus(`Starting Lean: loading module ${msg.loaded} of ${msg.total}`);
      } else if (msg.type === 'ready') {
        if (msg.error) return this.fail(msg.error);
        if (!msg.ok) return this.fail('importing the modules the book needs failed');
        this.state = 'ready';
        // Whether this runtime answers position queries (goals, hover text,
        // completions); older ones only compile.
        this.queries = !!msg.queries;
        this.setStatus('Lean is ready.');
      } else if (msg.type === 'failed') {
        this.fail(msg.error);
      } else if (msg.type === 'answer') {
        const resolve = this.pending.get(msg.id);
        this.pending.delete(msg.id);
        if (resolve) resolve(msg);
      }
    },

    fail(error) {
      this.state = 'failed';
      this.setStatus('Lean could not start in this browser: ' + error);
      for (const resolve of this.pending.values()) resolve({ ok: false, error });
      this.pending.clear();
    },

    setStatus(text) {
      this.status = text;
      for (const f of this.listeners) f();
    },

    whenReady() {
      if (this.state === 'ready' || this.state === 'failed') return Promise.resolve();
      return new Promise((resolve) => {
        const check = () => {
          if (this.state === 'ready' || this.state === 'failed') {
            this.listeners.delete(check);
            resolve();
          }
        };
        this.listeners.add(check);
      });
    },

    // Send `msg` once Lean is ready; resolves with the worker's answer.
    async ask(msg) {
      await this.whenReady();
      if (this.state !== 'ready') return { ok: false, error: this.status };
      const id = this.nextId++;
      return new Promise((resolve) => {
        this.pending.set(id, resolve);
        this.worker.postMessage({ ...msg, id });
      });
    },

    // Check `code` as the continuation of `context`.
    compile(code, context) {
      return this.ask({ type: 'compile', code, context });
    },

    // Check `code` unless it was checked last, and report what Lean has at
    // `line` (1-based) and `column` (in codepoints) of it: { result, info }.
    info(code, context, line, column) {
      return this.ask({ type: 'info', code, context, line, column });
    },

    // Likewise, the completions there: { result, completions }.
    complete(code, context, line, column) {
      return this.ask({ type: 'complete', code, context, line, column });
    },

    // The type and docstring of item `index` of the last completions: { item }.
    resolve(index) {
      return this.ask({ type: 'resolve', index });
    },
  };

  // Lean's threads share memory, which browsers allow only on cross-origin
  // isolated pages.  If the server did not send the headers for that, the
  // service worker in sfl-lean-isolation.js adds them, after one reload.
  async function ensureIsolated(reopen) {
    if (self.crossOriginIsolated) return true;
    if (sessionStorage.getItem(STORE + 'isolation-tried')) return false;
    sessionStorage.setItem(STORE + 'isolation-tried', '1');
    try {
      await navigator.serviceWorker.register(new URL('../sfl-lean-isolation.js', here), { scope: new URL('..', here).pathname });
      await navigator.serviceWorker.ready;
    } catch (e) {
      return false;
    }
    sessionStorage.setItem(STORE + 'reopen', reopen);
    location.reload();
    return new Promise(() => {}); // the page is going away
  }

  // ── Diagnostics ───────────────────────────────────────────────────────────

  // Lean's messages about the reader's code, at the editor's lines and
  // columns; errors from the context before it are kept apart.  A compile
  // that failed outright has an `error` and is never a success.
  function describe(result, code) {
    const codeLine = result.codeLine || 1;
    const lines = code.split('\n');
    const at = (pos) => {
      const line = pos.line - codeLine + 1;
      return { line, col: jsOffset(lines[line - 1] || '', pos.column) };
    };
    const own = [];
    const context = [];
    for (const m of result.messages || []) {
      if (!m.context && m.pos.line >= codeLine) {
        const start = at(m.pos);
        const end = m.endPos ? at(m.endPos) : start;
        own.push({ ...m, line: start.line, col: start.col, endLine: end.line, endCol: end.col });
      } else if (m.severity === 'error') {
        context.push(m);
      }
    }
    return { own, context, error: result.ok ? null : (result.error || 'Lean could not check this') };
  }

  // The suggestions in a "Try this" message of a search tactic such as `rw?`
  // or `exact?`: each a replacement for the tactic, with notes such as the
  // goal it would leave.  Lean writes each as an `[apply] <tactic>` line (the
  // text of the button Lean's editors show), the lines of a long tactic that
  // continue it indented further, then its notes as `--` comments.
  function suggestions(m) {
    if (!/^Try th(is|ese):/.test(m.data)) return null;
    const out = [];
    let indent = 0;
    for (const line of m.data.split('\n').slice(1)) {
      const apply = /^(\s*)\[apply\]\s?(.*)$/.exec(line);
      const last = out[out.length - 1];
      if (apply) {
        indent = apply[1].length;
        out.push({ text: apply[2], notes: [] });
      } else if (!last || !line.trim()) {
        continue;
      } else if (line.search(/\S/) > indent && !last.notes.length && !line.trim().startsWith('--')) {
        last.text += '\n' + line.slice(indent);
      } else {
        last.notes.push(line.trim());
      }
    }
    return out.length ? out : null;
  }

  // `rw?` also reports each lemma that matched but whose rewrite failed, and
  // `apply?` each partial proof whose tactic failed: `failure` says which
  // such report a message is, if any.
  const FAILURES = {
    rewrite: {
      pattern: /^found an applicable rewrite lemma, but the corresponding tactic failed/,
      summary: (n) => `${n} more lemma${n > 1 ? 's' : ''} matched, but rewriting with ${n > 1 ? 'them' : 'it'} failed`,
    },
    partial: {
      pattern: /^found a partial proof, but the corresponding tactic failed/,
      summary: (n) => `${n} more partial proof${n > 1 ? 's were' : ' was'} found, but ${n > 1 ? 'their tactics' : 'its tactic'} failed`,
    },
  };
  function failure(m) {
    return Object.keys(FAILURES).find((kind) => FAILURES[kind].pattern.test(m.data)) || null;
  }

  // A list of Lean's messages as the editor shows it.  When `apply?` finds
  // no whole proof it reports every partial one, a message each, a hundred
  // or more: the suggestions made at one place are shown as one message, and
  // the failed attempts are folded into one line per kind, at the end.
  // Entries are `{ message, offered }`, `offered` being the suggestions, or
  // `{ failed, messages }`.
  function grouped(messages) {
    const entries = [], at = new Map(), failed = new Map();
    for (const m of messages) {
      const kind = failure(m);
      const offered = !kind && suggestions(m);
      if (kind) {
        if (!failed.has(kind)) failed.set(kind, []);
        failed.get(kind).push(m);
      } else if (offered && at.has(m.line + ':' + m.col)) {
        at.get(m.line + ':' + m.col).offered.push(...offered);
      } else {
        const entry = { message: m, offered: offered || null };
        if (offered) at.set(m.line + ':' + m.col, entry);
        entries.push(entry);
      }
    }
    for (const [kind, list] of failed) entries.push({ failed: kind, messages: list });
    return entries;
  }

  // How many messages a list shows.
  function shownCount(messages) {
    return grouped(messages).length;
  }

  // How many suggestions a message shows before folding the rest.
  const SHOWN_SUGGESTIONS = 3;

  // How the editor marks a message: `done` is Lean's silent "Goals
  // accomplished!" on a declaration it accepted.
  function category(m) {
    if (m.kind === 'goalsAccomplished') return 'done';
    if (isUnsolvedGoals(m)) return 'goals';
    return m.severity === 'error' ? 'error' : m.severity === 'warning' ? 'warning' : 'info';
  }

  // What a check says of the reader's code.  A solution is code Lean accepts
  // with no goals left and no `sorry`.
  function verdict({ own, context, error }, block) {
    const errors = own.filter((m) => category(m) === 'error').length;
    // Goals left at the end only mean "not finished"; the goal view shows
    // them, so they are counted, not listed.
    const left = own.filter(isUnsolvedGoals).reduce((n, m) => n + (m.data.match(/^⊢/gm) || []).length, 0);
    const sorry = own.some((m) => m.kind === 'hasSorry' || /declaration uses `?sorry`?/.test(m.data));
    const solved = !errors && !left && !sorry && !context.length && !error;
    const text = error ? 'Lean could not check this.'
      : errors ? `${errors} error${errors > 1 ? 's' : ''}`
        : left ? `Not finished yet: ${left} goal${left > 1 ? 's' : ''} left`
          : sorry ? 'No errors, but the proof still uses sorry'
            : block ? '✓ Lean accepts this'
              : '✓ Lean accepts this; the exercises after it will use your solution';
    return { solved, text };
  }

  // Where squiggles overlap, the stronger one shows.
  const STRENGTH = { goals: 1, info: 2, warning: 3, error: 4 };

  // A highlighted line's pieces, split where squiggles start and end.
  function decorate(pieces, ranges) {
    if (!pieces.length) return [' '];
    const length = pieces.reduce((n, [, t]) => n + t.length, 0);
    const marks = new Array(length).fill(null);
    for (const r of ranges || []) {
      for (let i = r.from; i < Math.min(r.to, length); i++) {
        if (!marks[i] || STRENGTH[r.kind] > STRENGTH[marks[i]]) marks[i] = r.kind;
      }
    }
    const out = [];
    let pos = 0;
    for (const [cls, t] of pieces) {
      let start = 0;
      for (let i = 1; i <= t.length; i++) {
        if (i < t.length && marks[pos + i] === marks[pos + start]) continue;
        const mark = marks[pos + start];
        const classes = [cls && 'sfl-tok-' + cls, mark && 'sfl-sq-' + mark].filter(Boolean).join(' ');
        out.push(classes ? el('span', { class: classes }, t.slice(start, i)) : t.slice(start, i));
        start = i;
      }
      pos += t.length;
    }
    return out;
  }

  // ── Typing Lean's symbols ──────────────────────────────────────────────────────

  // The abbreviations Lean's editors expand after a backslash (`\to` is `→`):
  // Lean's own, from abbreviations.json (copied from @leanprover/unicode-input
  // 0.1.11, Apache-2.0, the table VS Code uses), fetched when the first editor
  // opens, and the book's own, from its .vscode/settings.json.
  const BOOK_ABBREVIATIONS = { tc: '⦂', llrr: '↞↠' };
  let ABBREVIATIONS = BOOK_ABBREVIATIONS;
  let abbreviationsLoading = null;

  function loadAbbreviations() {
    abbreviationsLoading = abbreviationsLoading || fetch(new URL('abbreviations.json', here))
      .then((response) => (response.ok ? response.json() : {}))
      .then((table) => { ABBREVIATIONS = { ...table, ...BOOK_ABBREVIATIONS }; })
      .catch(() => { /* only the book's own abbreviations, then */ });
    return abbreviationsLoading;
  }

  // The symbols this book uses most, offered first when only a backslash has
  // been typed.
  const COMMON_ABBREVIATIONS = [
    'to', 'l', 'iff', 'and', 'or', 'not', 'forall', 'exists', 'ne', 'le', 'ge', '.', 'x', 'circ',
    'fun', 'N', 'in', 'notin', 'sub', 'cup', 'cap', 'empty', '<>', 'a', 'b', 'g', '|-', 'top', 'bot',
    'heq', 'tc',
  ];

  // An abbreviation's symbol as text, and where in it the cursor goes: some,
  // such as `\<>` for `⟨⟩`, put it between a pair.
  function symbolText(symbol) {
    const at = symbol.indexOf('$CURSOR');
    return at < 0 ? { text: symbol, cursor: symbol.length } : { text: symbol.replace('$CURSOR', ''), cursor: at };
  }

  // ── Highlighting ──────────────────────────────────────────────────────────

  // The static code blocks are colored by Lean itself, which knows what each
  // name refers to.  The editor colors by spelling alone, in the same palette:
  // keywords and tactics as keywords, capitalized or qualified names as
  // constants, and comments muted.
  const KEYWORDS = new Set((
    'import export prelude theorem lemma example axiom inductive coinductive structure class ' +
    'instance abbrev def meta partial unsafe noncomputable mutual namespace section end universe ' +
    'variable open set_option attribute macro macro_rules syntax notation infix infixl infixr prefix ' +
    'deriving where extends protected private public scoped local do by let fun match with if then ' +
    'else have show suffices calc this from return try catch finally for in unless at sorry admit ' +
    'termination_by decreasing_by exists Prop Type Sort λ ' +
    // Tactics this book uses.
    'intro intros exact apply rw rewrite rfl constructor cases induction obtain simp simp_all case ' +
    'contradiction inversion injection injections ext by_cases left right exfalso assumption repeat ' +
    'subst change congr symm specialize unfold fold omega decide lia trivial refine use revert ' +
    'generalize clear rename_i first all_goals any_goals next nofun nomatch funext split ' +
    'solution! workinclass! suggested!').split(' '));

  const TOKEN = new RegExp([
    /(--.*)/.source,                                    // 1 line comment
    /(\/-)/.source,                                     // 2 block comment start
    /("(?:[^"\\\n]|\\.)*"?)/.source,                    // 3 string
    /(#[A-Za-z_]+)/.source,                             // 4 #command
    /(\d+(?:\.\d+)?)/.source,                           // 5 number
    /([A-Za-z_α-ωΑ-Ω][\w'α-ωΑ-Ωₐ-ₜ₀-₉ᵢ-ᵪ!?]*(?:\.[A-Za-z_α-ωΑ-Ω][\w'α-ωΑ-Ωₐ-ₜ₀-₉ᵢ-ᵪ!?]*)*)/.source, // 6 name
  ].join('|'), 'gu');

  function nameTokens(name, out) {
    if (KEYWORDS.has(name)) return out.push(['kw', name]);
    // `h.left`: a local name followed by fields; color the fields only.
    const dot = name.indexOf('.');
    if (/^[A-Z]/.test(name)) return out.push(['const', name]);
    if (dot > 0) return out.push(['', name.slice(0, dot)], ['const', name.slice(dot)]);
    out.push(['', name]);
  }

  // The text as lines of [class, text] pieces.
  function highlight(text) {
    const tokens = [];
    let pos = 0;
    while (pos < text.length) {
      TOKEN.lastIndex = pos;
      const m = TOKEN.exec(text);
      if (!m) { tokens.push(['', text.slice(pos)]); break; }
      if (m.index > pos) tokens.push(['', text.slice(pos, m.index)]);
      pos = m.index + m[0].length;
      if (m[1]) tokens.push(['comment', m[1]]);
      else if (m[2]) {
        // Block comments nest.
        let depth = 1;
        let i = m.index + 2;
        while (i < text.length && depth > 0) {
          if (text.startsWith('/-', i)) { depth++; i += 2; }
          else if (text.startsWith('-/', i)) { depth--; i += 2; }
          else i++;
        }
        tokens.push(['comment', text.slice(m.index, i)]);
        pos = i;
      } else if (m[3]) tokens.push(['string', m[3]]);
      else if (m[4]) tokens.push(['kw', m[4]]);
      else if (m[5]) tokens.push(['', m[5]]);
      else nameTokens(m[6], tokens);
    }
    const lines = [[]];
    for (const [cls, t] of tokens) {
      const parts = t.split('\n');
      parts.forEach((p, i) => {
        if (i > 0) lines.push([]);
        if (p) lines[lines.length - 1].push([cls, p]);
      });
    }
    return lines;
  }

  // The abbreviation (`\to`, say) just before the cursor: where it starts and
  // the symbol it stands for.
  function abbreviationBefore(textarea) {
    const pos = textarea.selectionStart;
    const m = /\\([^\s\\]+)$/.exec(textarea.value.slice(0, pos));
    return m && m[1] in ABBREVIATIONS ? { start: pos - m[0].length, symbol: ABBREVIATIONS[m[1]] } : null;
  }

  // ── The infoview ──────────────────────────────────────────────────────────

  // Which infoview sections the reader has folded, kept while the page is open.
  const foldedSections = new Set();

  function infoSection(key, title, children) {
    const section = el('details', { class: 'sfl-info-section' }, el('summary', {}, title), ...children);
    section.open = !foldedSections.has(key);
    section.addEventListener('toggle', () => {
      if (section.open) foldedSections.delete(key);
      else foldedSections.add(key);
    });
    return section;
  }

  // Lean's editors show goals and messages in an infoview beside the code.
  // Where the page leaves room right of the book's text, the focused editor
  // shows its infoview there, in this panel, which stays in view as the page
  // scrolls; elsewhere the same view sits under the editor.
  const INFOVIEW_WIDTH = 300; // the narrowest worth showing, in px
  const infoview = {
    node: null,
    head: null,
    body: null,
    owner: null,
    editors: new Set(),

    ensure() {
      if (this.node) return;
      this.head = el('div', { class: 'sfl-infoview-head' });
      this.body = el('div', { class: 'sfl-infoview-body' });
      // Focusable, so that clicking in it, to select text say, keeps it open.
      this.node = el('aside', { class: 'sfl-infoview', tabindex: '-1', 'aria-label': 'Lean infoview', hidden: '' },
        this.head, this.body);
      document.body.append(this.node);
      this.node.addEventListener('focusout', () => setTimeout(() => this.owner && this.owner.updateInfoview()));
      window.addEventListener('scroll', () => {
        if (this.frame) return;
        this.frame = requestAnimationFrame(() => { this.frame = null; this.place(); });
      }, { passive: true });
      window.addEventListener('resize', () => { for (const editor of this.editors) editor.updateInfoview(); });
    },

    // Right of the exercise, level with the editor, and inside the window
    // below the page's fixed header.
    place() {
      const editor = this.owner;
      if (!editor || this.node.hidden) return;
      const header = document.querySelector('body > header');
      const top = Math.max(header ? header.getBoundingClientRect().bottom : 0, 0) + 12;
      const left = editor.box.getBoundingClientRect().right + 24;
      const width = Math.min(480, document.documentElement.clientWidth - left - 24);
      const height = this.node.offsetHeight;
      this.node.style.left = left + 'px';
      this.node.style.width = width + 'px';
      this.node.style.maxHeight = (window.innerHeight - top - 12) + 'px';
      this.node.style.top = Math.max(top, Math.min(editor.root.getBoundingClientRect().top,
        window.innerHeight - 12 - height)) + 'px';
    },
  };

  // ── Completion ────────────────────────────────────────────────────────────

  // The name being typed before `pos`: `token` is the whole dotted name and
  // `segment` its part after the last dot, which a completion replaces.  A
  // number, or an abbreviation such as `\to`, is not a name.
  function nameBefore(text, pos) {
    const token = /[\w'α-ωΑ-Ωₐ-ₜ₀-₉ᵢ-ᵪ!?.]*$/u.exec(text.slice(0, pos))[0];
    if (/^\d/.test(token) || text[pos - token.length - 1] === '\\') return null;
    const segment = token.slice(token.lastIndexOf('.') + 1);
    return { token, segment, start: pos - segment.length, pos };
  }

  // How well a completion matches what has been typed, or -1.  Lean already
  // left out names that do not match at all; this ranks the rest as typing
  // narrows them: a prefix of the name's last component first, then other
  // prefixes, inner substrings, and scattered letters, each shorter name and
  // shallower namespace first.
  function matchScore(label, typed) {
    const last = label.slice(label.lastIndexOf('.') + 1);
    const depth = 3 * (label.split('.').length - 1);
    if (!typed) return 5000 - last.length - depth;
    const lower = last.toLowerCase();
    const want = typed.toLowerCase();
    if (last.startsWith(typed)) return 4000 - last.length - depth;
    if (lower.startsWith(want)) return 3000 - last.length - depth;
    if (label.toLowerCase().startsWith(want)) return 2500 - label.length;
    const at = lower.indexOf(want);
    if (at >= 0) return 2000 - 10 * at - last.length - depth;
    let i = 0;
    for (const c of lower) if (c === want[i]) i++;
    return i === want.length ? 1000 - last.length - depth : -1;
  }

  // `label` with the typed letters in bold, where they appear together.
  function labelPieces(label, typed) {
    const lower = label.toLowerCase();
    const want = typed.toLowerCase();
    const inLast = lower.indexOf(want, label.lastIndexOf('.') + 1);
    const at = inLast >= 0 ? inLast : lower.indexOf(want);
    if (!want || at < 0) return [label];
    return [label.slice(0, at), el('b', {}, label.slice(at, at + want.length)), label.slice(at + want.length)];
  }

  // Lean's completion kinds (LSP numbers), as the words a reader knows.
  const KINDS = {
    3: 'fun', 4: 'ctor', 5: 'field', 6: 'var', 7: 'class', 9: 'ns', 10: 'option',
    13: 'type', 14: 'tactic', 21: 'def', 22: 'type', 23: 'thm',
  };

  // ── The editor ────────────────────────────────────────────────────────────

  // Edits an exercise, or a block from the text.  `box` is what the editor
  // sits in, and `hidden` the book's code it stands in for while open.
  class ExerciseEditor {
    constructor(data, exercise, box, hidden = [...box.querySelectorAll('code.hl.lean.block')]) {
      this.data = data;
      this.exercise = exercise;
      this.box = box;
      // A block's draft is kept under its code, so that it does not come back
      // on a block whose code has since changed.
      this.key = data.chapter + ':' + (exercise.block ? 'block:' + hashCode(exercise.code) : exercise.name);
      this.hidden = hidden;

      this.textarea = el('textarea', {
        class: 'sfl-input', spellcheck: 'false', autocapitalize: 'off', autocomplete: 'off',
        'aria-label': exercise.block ? `Lean code from the text: ${exercise.name}` : `Lean code for exercise ${exercise.name}`,
      });
      this.textarea.value = load('draft:' + this.key) ?? exercise.code;
      this.handledValue = this.textarea.value;
      this.backdrop = el('div', { class: 'sfl-backdrop', 'aria-hidden': 'true' });
      this.gutter = el('div', { class: 'sfl-gutter', 'aria-hidden': 'true' });
      this.tooltip = el('div', { class: 'sfl-tooltip', role: 'tooltip', hidden: '' });
      this.completionList = el('div', { class: 'sfl-complete-list' });
      this.completionDetail = el('div', { class: 'sfl-complete-detail', hidden: '' });
      this.popup = el('div', { class: 'sfl-complete', role: 'listbox', hidden: '' },
        this.completionList, this.completionDetail);
      this.area = el('div', { class: 'sfl-area' }, this.backdrop, this.textarea, this.tooltip, this.popup);
      this.runButton = el('button', { class: 'sfl-run', type: 'button', onclick: () => this.run() }, 'Run');
      this.status = el('span', { class: 'sfl-status', role: 'status' });
      this.messages = el('div', { class: 'sfl-messages' });
      this.goals = el('div', { class: 'sfl-goals', 'aria-live': 'polite' });
      this.bar = el('div', { class: 'sfl-bar' }, this.runButton,
        el('span', { class: 'sfl-hint' }, navigator.platform.startsWith('Mac') ? '⌘↵' : 'Ctrl+↵'),
        this.status);
      this.root = el('div', { class: 'sfl-editor' },
        el('div', { class: 'sfl-code' }, this.gutter, this.area),
        this.goals,
        this.bar,
        this.messages);

      // Lean's messages about the code, at editor positions (see describe).
      this.diagnostics = [];
      this.squiggles = [];
      this.completion = null;
      this.completionSeq = 0;

      this.textarea.addEventListener('input', (e) => this.onInput(e));
      this.textarea.addEventListener('keydown', (e) => this.onKey(e));
      // Moving the cursor shows what Lean has at the new place.
      this.textarea.addEventListener('click', () => this.onCursorMove());
      this.textarea.addEventListener('keyup', (e) => {
        if (/^(Arrow|Home|End|Page)/.test(e.key)) this.onCursorMove();
      });
      // The textarea grows to fit its text, so only long lines scroll.
      this.textarea.addEventListener('scroll', () => {
        this.backdrop.scrollLeft = this.textarea.scrollLeft;
        this.hideTooltip();
      });
      this.textarea.addEventListener('mousemove', (e) => this.onMouseMove(e.clientX, e.clientY));
      this.textarea.addEventListener('mouseleave', () => this.leaveHover());
      this.textarea.addEventListener('blur', () => setTimeout(() => {
        if (document.activeElement !== this.textarea) this.closeCompletion();
      }, 150));
      this.tooltip.addEventListener('mouseenter', () => clearTimeout(this.hideTimer));
      this.tooltip.addEventListener('mouseleave', () => this.leaveHover());
      // Clicking the list must not take the focus from the code.
      this.popup.addEventListener('mousedown', (e) => e.preventDefault());
      // Clicking a lightbulb must not take the focus from the code either.
      this.gutter.addEventListener('mousedown', (e) => e.preventDefault());
      this.gutter.addEventListener('click', (e) => {
        const row = e.target.closest('.sfl-g-fix');
        if (!row) return;
        const line = Array.prototype.indexOf.call(this.gutter.children, row) + 1;
        this.showSuggestionsAt(line, row.querySelector('.sfl-mark').getBoundingClientRect());
      });
      this.root.addEventListener('focusin', () => this.updateInfoview());
      this.root.addEventListener('focusout', () => setTimeout(() => this.updateInfoview()));
      this.onLean = () => this.showStatus();
      lean.listeners.add(this.onLean);
      loadAbbreviations();
    }

    open() {
      infoview.ensure();
      infoview.editors.add(this);
      const anchor = this.hidden[this.hidden.length - 1] || this.box.lastElementChild;
      anchor.after(this.root);
      for (const block of this.hidden) block.classList.add('sfl-replaced');
      this.render();
      this.showStatus();
      this.textarea.focus();
      // Start where the reader has work to do: at the first `sorry` of the
      // code, not of a comment.
      const todo = this.firstSorry();
      const at = todo >= 0 ? todo : this.textarea.value.trimEnd().length;
      this.textarea.setSelectionRange(at, at);
      this.updateInfoview();
      this.scheduleCheck(0);
    }

    firstSorry() {
      let offset = 0;
      for (const pieces of highlight(this.textarea.value)) {
        for (const [cls, t] of pieces) {
          if (cls === 'kw' && t === 'sorry') return offset;
          offset += t.length;
        }
        offset += 1;
      }
      return -1;
    }

    close() {
      for (const timer of [this.checkTimer, this.hoverTimer, this.hideTimer, this.completeTimer]) clearTimeout(timer);
      this.closed = true;
      for (const block of this.hidden) block.classList.remove('sfl-replaced');
      this.root.remove();
      lean.listeners.delete(this.onLean);
      infoview.editors.delete(this);
      if (infoview.owner === this) {
        infoview.owner = null;
        infoview.node.hidden = true;
      }
    }

    reset() {
      this.textarea.value = this.exercise.code;
      this.handledValue = this.textarea.value;
      save('draft:' + this.key, null);
      save('solved:' + this.key, null);
      this.reported = false;
      this.root.classList.remove('sfl-solved');
      this.showStatus();
      this.diagnostics = [];
      this.messages.replaceChildren();
      this.closeCompletion();
      this.hideTooltip();
      this.render();
      this.scheduleCheck(0);
    }

    context(code) {
      return compose(this.data, this.exercise, code, { useAnswers: true }).context;
    }

    // `offset` in the text as a 1-based line, the editor's column in it, and
    // Lean's (codepoint) column.
    position(offset, text = this.textarea.value) {
      const lineStart = text.lastIndexOf('\n', offset - 1) + 1;
      const lineEnd = text.indexOf('\n', offset);
      const lineText = text.slice(lineStart, lineEnd < 0 ? text.length : lineEnd);
      const col = offset - lineStart;
      return { line: text.slice(0, offset).split('\n').length, col, column: leanColumn(lineText, col) };
    }

    onInput(e) {
      // Chrome reports a line break and the indentation after it, inserted as
      // one edit, as two input events.
      if (this.textarea.value === this.handledValue) return;
      this.handledValue = this.textarea.value;
      save('draft:' + this.key, this.textarea.value === this.exercise.code ? null : this.textarea.value);
      // A run's list of messages was about the code before this edit.  The
      // verdict and the goal view stay until the next check replaces them,
      // which comes once typing pauses; they are greyed only if it is slow to
      // come, so that typing does not make them flicker.
      this.messages.replaceChildren();
      clearTimeout(this.pendingTimer);
      this.pendingTimer = setTimeout(() => this.setPending(true), 1000);
      this.hideTooltip();
      this.render();
      this.scheduleCheck(400);
      // Typing a backslash lists the symbols its abbreviations stand for;
      // typing a name, or a dot after one, asks Lean what could go there;
      // erasing keeps an open list in step.
      const typed = e.inputType === 'insertText' && !this.editing;
      const erased = (e.inputType || '').startsWith('delete') && !this.editing && this.completion;
      if ((typed || erased) && this.abbreviationTyped()) this.showSymbols();
      else if ((typed && /[\w'α-ωΑ-Ωₐ-ₜ₀-₉ᵢ-ᵪ!?.]$/u.test(e.data || '')) || erased) this.updateCompletion(200);
      else this.closeCompletion();
    }

    onCursorMove() {
      this.scheduleCheck(150);
      if (this.completion && this.completion.symbols) this.showSymbols();
      else if (this.completion) this.showCompletions();
    }

    onKey(e) {
      if ((e.metaKey || e.ctrlKey) && e.key === '.' && this.applyFirstSuggestion()) {
        e.preventDefault();
        return;
      }
      if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') {
        e.preventDefault();
        this.run();
        return;
      }
      if (this.completion && !this.popup.hidden) {
        if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
          e.preventDefault();
          this.selectCompletion(this.completion.selected + (e.key === 'ArrowDown' ? 1 : -1));
          return;
        }
        if (e.key === 'Enter' || e.key === 'Tab') {
          e.preventDefault();
          this.acceptCompletion(this.completion.shown[this.completion.selected]);
          return;
        }
        if (e.key === 'Escape') {
          e.preventDefault();
          this.closeCompletion();
          return;
        }
      }
      if (e.ctrlKey && e.key === ' ') {
        e.preventDefault();
        this.updateCompletion(0);
      } else if (e.key === 'Escape') {
        this.hideTooltip();
      } else if (e.key === 'Tab') {
        e.preventDefault();
        const ta = this.textarea;
        const lines = ta.value.slice(ta.selectionStart, ta.selectionEnd).includes('\n');
        if (e.shiftKey || lines) this.shiftLines(e.shiftKey);
        else if (!this.expandAbbreviation()) this.edit('  ');
      } else if (e.key === 'Enter' && !e.altKey && !e.isComposing) {
        e.preventDefault();
        this.newLine();
      } else if (e.key === 'Backspace' && !e.metaKey && !e.ctrlKey && !e.altKey && !e.isComposing && this.dedent()) {
        e.preventDefault();
      } else if (e.key === ' ') {
        this.expandAbbreviation();
      }
    }

    // Put `text` in as typing does, so that the browser's undo takes it back;
    // `execCommand` is the only way to get that in a textarea.  Where it is
    // unavailable the edit is made directly.
    //
    // The text replaced runs from `from` to `to` (the selection, by default).
    // Afterwards the cursor is `caret` characters into `text` (at its end, by
    // default), or `text` is selected.  An edit made here never opens a
    // completion list.
    edit(text, { from = this.textarea.selectionStart, to = this.textarea.selectionEnd, caret, select } = {}) {
      const ta = this.textarea;
      ta.setSelectionRange(from, to);
      this.editing = true;
      try {
        const done = text ? document.execCommand('insertText', false, text)
          : from === to || document.execCommand('delete');
        if (!done) {
          ta.setRangeText(text, from, to, 'end');
          ta.dispatchEvent(new Event('input'));
        }
      } finally {
        this.editing = false;
      }
      if (select) ta.setSelectionRange(from, from + text.length);
      else if (caret !== undefined) ta.setSelectionRange(from + caret, from + caret);
    }

    // Replace the abbreviation before the cursor (`\to`, say) with its symbol.
    expandAbbreviation() {
      const abbreviation = abbreviationBefore(this.textarea);
      if (!abbreviation) return false;
      const { text, cursor } = symbolText(abbreviation.symbol);
      this.edit(text, { from: abbreviation.start, to: this.textarea.selectionStart, caret: cursor });
      return true;
    }

    // Tab over a selection of lines indents each by a level, and Shift+Tab
    // unindents the selected lines, or the cursor's, as Lean's editors do.  A
    // selection that ends at the start of a line leaves that line alone.
    shiftLines(unindent) {
      const ta = this.textarea;
      const value = ta.value;
      const start = value.lastIndexOf('\n', ta.selectionStart - 1) + 1;
      let end = ta.selectionEnd;
      if (end > ta.selectionStart && value[end - 1] === '\n') end--;
      const lineEnd = value.indexOf('\n', end);
      const stop = lineEnd < 0 ? value.length : lineEnd;
      const lines = value.slice(start, stop).split('\n');
      const shifted = lines.map((l) => (unindent ? l.replace(/^ {1,2}/, '') : l ? '  ' + l : l));
      const text = shifted.join('\n');
      if (text === value.slice(start, stop)) return;
      if (ta.selectionStart === ta.selectionEnd) {
        const removed = lines[0].length - shifted[0].length;
        this.edit(text, { from: start, to: stop, caret: Math.max(0, ta.selectionStart - start - removed) });
      } else {
        this.edit(text, { from: start, to: stop, select: true });
      }
    }

    // Enter starts a line indented like the cursor's, as Lean's editors do.
    // An abbreviation before the cursor is expanded in the same edit.
    newLine() {
      const ta = this.textarea;
      const lineStart = ta.value.lastIndexOf('\n', ta.selectionStart - 1) + 1;
      const indent = /^[ \t]*/.exec(ta.value.slice(lineStart, ta.selectionStart))[0];
      const abbreviation = ta.selectionStart === ta.selectionEnd && abbreviationBefore(ta);
      if (abbreviation) ta.setSelectionRange(abbreviation.start, ta.selectionEnd);
      this.edit((abbreviation ? symbolText(abbreviation.symbol).text : '') + '\n' + indent);
    }

    // Backspace within a line's indentation removes a whole level, the two
    // spaces Tab inserts, back to the previous multiple of two.
    dedent() {
      const ta = this.textarea;
      const pos = ta.selectionStart;
      if (pos !== ta.selectionEnd) return false;
      const before = ta.value.slice(ta.value.lastIndexOf('\n', pos - 1) + 1, pos);
      if (!before || /[^ ]/.test(before)) return false;
      ta.setSelectionRange(pos - (before.length % 2 || 2), pos);
      this.edit('');
      return true;
    }

    // ── Checking as the reader types ──

    scheduleCheck(delay) {
      clearTimeout(this.checkTimer);
      this.checkTimer = setTimeout(() => this.check(), delay);
    }

    // Check the code (the worker skips this when it is unchanged), mark
    // Lean's messages in it, and show what Lean has at the cursor.  One check
    // runs at a time; one asked for meanwhile runs after it.
    async check() {
      if (this.closed) return;
      if (lean.state !== 'ready') {
        if (lean.state === 'failed') return;
        this.showInfo(undefined);
        if (!this.waitingForLean) {
          this.waitingForLean = true;
          lean.whenReady().then(() => { this.waitingForLean = false; this.check(); });
        }
        return;
      }
      if (this.checking) { this.checkAgain = true; return; }
      this.checking = true;
      const code = this.textarea.value;
      const cursor = this.position(this.textarea.selectionStart, code);
      const answer = await lean.info(code, this.context(code), cursor.line, cursor.column);
      this.checking = false;
      if (code === this.textarea.value && !this.closed) {
        clearTimeout(this.pendingTimer);
        this.setPending(false);
        if (answer.result) {
          const described = describe(answer.result, code);
          this.setDiagnostics(described.own, code);
          this.judge(described, code);
        }
        this.showInfo(answer.info || null, cursor.line, cursor.column);
      }
      if (this.checkAgain) { this.checkAgain = false; this.check(); }
    }

    setPending(pending) {
      this.root.classList.toggle('sfl-pending', pending);
      if (infoview.owner === this) infoview.node.classList.toggle('sfl-pending', pending);
    }

    // Lean's messages about `code`, which suggestions may only be applied to.
    setDiagnostics(own, code) {
      this.diagnostics = own;
      this.diagnosticsCode = code;
      this.render();
    }

    // The infoview, after Lean's editors': the goals at the cursor, the type
    // expected there, Lean's messages about the cursor's line and, beside the
    // text, about the whole exercise.  `info` is undefined while Lean is
    // starting and null when Lean has nothing to say at the cursor.
    showInfo(info, line, column) {
      this.info = { info, line, column };
      this.renderInfo();
    }

    // Show the infoview beside the book's text while this editor, or the
    // infoview, has the focus and the page has room; otherwise under the
    // editor, or not at all when the room is there but the focus is not.
    updateInfoview() {
      if (this.closed) return;
      const room = document.documentElement.clientWidth - this.box.getBoundingClientRect().right - 48;
      const beside = room >= INFOVIEW_WIDTH;
      const moved = beside !== this.root.classList.contains('sfl-beside');
      this.root.classList.toggle('sfl-beside', beside);
      const active = document.activeElement;
      const shown = infoview.owner === this && !infoview.node.hidden;
      if (beside && (this.root.contains(active) || infoview.node.contains(active))) {
        if (shown) {
          infoview.place();
        } else {
          infoview.owner = this;
          infoview.node.hidden = false;
          this.renderInfo();
        }
      } else if (shown) {
        infoview.owner = null;
        infoview.node.hidden = true;
      }
      if (moved && !beside) this.renderInfo();
    }

    renderInfo() {
      if (!this.info) return;
      const beside = this.root.classList.contains('sfl-beside');
      if (beside && infoview.owner !== this) return;
      const { info, line, column } = this.info;
      const sections = this.infoSections(info, line, beside);
      if (!beside) {
        this.goals.replaceChildren(...sections);
        return;
      }
      // Replacing what has the focus would drop it to the page, which hides
      // the infoview; the infoview itself keeps it instead.
      if (infoview.node.contains(document.activeElement)) infoview.node.focus({ preventScroll: true });
      infoview.head.textContent = `${this.exercise.name}:${line}:${column}`;
      infoview.body.replaceChildren(...sections);
      infoview.node.classList.toggle('sfl-pending', this.root.classList.contains('sfl-pending'));
      infoview.place();
    }

    infoSections(info, line, all) {
      if (info === undefined) {
        return [el('p', { class: 'sfl-goals-note' }, 'The goals at the cursor appear here once Lean has started.')];
      }
      const sections = [];
      const goals = info && info.goals;
      const here = this.diagnostics.filter((m) =>
        m.line === line && (!m.isSilent || category(m) === 'done') && !isUnsolvedGoals(m));
      if (goals) {
        // After a failed step Lean gives up on its goal, so there are none
        // left there, but the proof is not done.
        const failed = here.some((m) => m.severity === 'error');
        sections.push(infoSection('goals', 'Tactic state', goals.length
          ? [el('div', { class: 'sfl-goals-count' }, `${goals.length} goal${goals.length > 1 ? 's' : ''}`),
            ...goals.map((g) => goalCard(g))]
          : [el('p', { class: 'sfl-goals-done' }, failed ? 'No goals' : 'No goals: this part of the proof is complete.')]));
      }
      // Inside a tactic proof the hypotheses are shown above, and often the
      // expected type is the goal itself.
      const term = info && info.termGoal;
      if (term && !(goals && goals.length && goals[0].target === term.target)) {
        sections.push(infoSection('expected', 'Expected type', [goalCard(term, { hyps: !goals })]));
      }
      if (here.length) {
        sections.push(infoSection('messages', `Messages (${shownCount(here)})`, this.messageItems(here)));
      }
      const every = this.diagnostics.filter((m) => !m.isSilent);
      if (all && every.length) {
        sections.push(infoSection('all', `All messages (${shownCount(every)})`, this.messageItems(every, true)));
      }
      if (!sections.length) {
        sections.push(el('p', { class: 'sfl-goals-note' }, 'Put the cursor in a proof to see its goals here.'));
      }
      return sections;
    }

    // A message of Lean's, with a link to its line when it is listed among
    // others.
    messageItem(m, link, offered) {
      return el('div', { class: 'sfl-message sfl-' + category(m) },
        link ? el('button', { class: 'sfl-where', type: 'button', onclick: () => this.goTo(m.line, m.col) },
          `line ${m.line}`) : null,
        this.messageBody(m, offered));
    }

    messageItems(messages, link) {
      return this.messageList(messages, (m, offered) => this.messageItem(m, link, offered));
    }

    // The elements of a list of messages, grouped as `grouped` says, each
    // drawn by `draw(message, suggestions)`.
    messageList(messages, draw) {
      return grouped(messages).map((entry) => entry.failed
        ? el('details', { class: 'sfl-failed' },
          el('summary', {}, FAILURES[entry.failed].summary(entry.messages.length)),
          ...entry.messages.map((m) => draw(m, null)))
        : draw(entry.message, entry.offered));
    }

    // A message's text; a "Try this" message offers its suggestions as links
    // that put each in place of the search tactic, as Lean's editors do.
    messageBody(m, offered = suggestions(m)) {
      if (!offered) return el('pre', {}, m.data);
      const item = (suggestion) => el('div', { class: 'sfl-suggestion' },
        el('button', {
          class: 'sfl-apply', type: 'button', title: 'Put this in place of the search',
          onclick: () => this.applySuggestion(m, suggestion),
        }, ...highlighted(suggestion.text)),
        ...suggestion.notes.map((note) => el('pre', { class: 'sfl-suggestion-note' }, ...highlighted(note))));
      const more = offered.slice(SHOWN_SUGGESTIONS);
      return el('div', { class: 'sfl-suggestions' },
        el('div', {}, offered.length > 1 ? 'Try these:' : 'Try this:'),
        ...offered.slice(0, SHOWN_SUGGESTIONS).map(item),
        ...(more.length
          ? [el('details', { class: 'sfl-more-suggestions' }, el('summary', {}, `${more.length} more`), ...more.map(item))]
          : []),
        el('div', { class: 'sfl-suggestions-hint' }, `${navigator.platform.startsWith('Mac') ? '⌘' : 'Ctrl+'}. applies the first`));
    }

    // Replace the search tactic Lean's message is about (`rw? at h`, say) with
    // `suggestion`.  The message starts at the tactic; the tactic runs to the
    // end of its line, or to a `;`, `<;>` or `)` after it.  A suggestion of
    // several lines keeps its indentation relative to the tactic.
    applySuggestion(m, suggestion) {
      const text = this.textarea.value;
      // A suggestion is about the code Lean checked; after an edit, the next
      // check brings new ones.
      if (text !== this.diagnosticsCode) return false;
      const lines = text.split('\n');
      const rest = (lines[m.line - 1] || '').slice(m.col);
      if (!/^[\w.]+\?/.test(rest)) return false;
      const end = rest.search(/\s*(<;>|;|\))/);
      let from = m.col;
      for (let i = 0; i < m.line - 1; i++) from += lines[i].length + 1;
      this.hideTooltip();
      this.textarea.focus();
      this.edit(suggestion.text.replace(/\n/g, '\n' + ' '.repeat(m.col)),
        { from, to: from + (end < 0 ? rest.trimEnd().length : end) });
      return true;
    }

    // ⌘. (Ctrl+.) applies the first suggestion on the cursor's line.
    applyFirstSuggestion() {
      const line = this.position(this.textarea.selectionStart).line;
      const m = this.diagnostics.find((d) => d.line === line && suggestions(d));
      return !!m && this.applySuggestion(m, suggestions(m)[0]);
    }

    // The suggestions on `line`, shown as a tooltip by its lightbulb.
    showSuggestionsAt(line, box) {
      const messages = this.diagnostics.filter((d) => d.line === line && suggestions(d));
      if (!messages.length) return;
      this.tooltip.replaceChildren(...this.messageList(messages, (m, offered) =>
        el('div', { class: 'sfl-tip-message sfl-tip-' + category(m) }, this.messageBody(m, offered))));
      this.hoverRange = null;
      this.place(this.tooltip, box);
    }

    // ── Drawing ──

    // Line numbers, and the highlighted code drawn under the textarea (whose
    // own text is transparent).  Lean's messages are drawn as Lean's editors
    // draw them: a squiggle under each message's first line, so a long one
    // does not paint the whole proof red; in the gutter, an icon where an
    // error or warning starts, a bracket along an error's full extent, and ✓✓
    // on each theorem Lean accepted.
    render() {
      const text = this.textarea.value;
      const lines = highlight(text);
      const raw = text.split('\n');
      const gutter = new Map();
      const mark = (line, cls) => {
        if (!gutter.has(line)) gutter.set(line, []);
        gutter.get(line).push(cls);
      };
      this.squiggles = [];
      for (const m of this.diagnostics) {
        const kind = category(m);
        const lineText = raw[m.line - 1];
        if (lineText === undefined) continue;
        if (kind === 'done') { mark(m.line, 'sfl-g-done'); continue; }
        if (m.isSilent || failure(m)) continue;
        if (suggestions(m)) mark(m.line, 'sfl-g-fix');
        let from = Math.min(m.col, lineText.length);
        let to = m.endLine > m.line ? lineText.length : Math.min(m.endCol, lineText.length);
        // A message about a point (say, the end of the input) still gets a
        // character to hover.
        if (to <= from) {
          if (from < lineText.length) to = from + 1;
          else if (lineText.length) { from = lineText.length - 1; to = lineText.length; }
        }
        if (to > from) this.squiggles.push({ line: m.line, from, to, kind, message: m });
        if (kind === 'error' || kind === 'warning') mark(m.line, 'sfl-g-' + kind);
        if (kind === 'error' && m.endLine > m.line) {
          for (let l = m.line; l <= Math.min(m.endLine, raw.length); l++) {
            mark(l, l === m.line ? 'sfl-g-span-start' : l === m.endLine ? 'sfl-g-span-end' : 'sfl-g-span');
          }
        }
      }
      this.gutter.replaceChildren(...lines.map((_, i) =>
        el('div', { class: ['sfl-gutter-row', ...(gutter.get(i + 1) || [])].join(' ') },
          el('span', { class: 'sfl-mark' }), String(i + 1))));
      this.backdrop.replaceChildren(...lines.map((pieces, i) =>
        el('div', { class: 'sfl-line' }, ...decorate(pieces, this.squiggles.filter((s) => s.line === i + 1)))));
      this.textarea.style.height = 'auto';
      this.textarea.style.height = Math.max(this.textarea.scrollHeight, 80) + 'px';
    }

    // The box of the character at `col` of `line`, in the highlighted copy.
    charBox(line, col) {
      const row = this.backdrop.children[line - 1];
      if (!row) return null;
      const walker = document.createTreeWalker(row, NodeFilter.SHOW_TEXT);
      let left = col;
      for (let t = walker.nextNode(); t; t = walker.nextNode()) {
        if (left < t.data.length) {
          const range = document.createRange();
          range.setStart(t, left);
          range.setEnd(t, left + 1);
          return range.getBoundingClientRect();
        }
        left -= t.data.length;
      }
      return null;
    }

    // The character under the mouse, found in the highlighted copy, which is
    // laid out exactly as the textarea's text: { line, col, box }, or null off
    // the text.
    hitTest(x, y) {
      const { textarea, backdrop } = this;
      let node = null;
      let offset = 0;
      textarea.style.pointerEvents = 'none';
      backdrop.style.pointerEvents = 'auto';
      try {
        if (document.caretPositionFromPoint) {
          const p = document.caretPositionFromPoint(x, y);
          if (p) { node = p.offsetNode; offset = p.offset; }
        } else if (document.caretRangeFromPoint) {
          const r = document.caretRangeFromPoint(x, y);
          if (r) { node = r.startContainer; offset = r.startOffset; }
        }
      } finally {
        textarea.style.pointerEvents = '';
        backdrop.style.pointerEvents = '';
      }
      if (!node || node.nodeType !== Node.TEXT_NODE || !backdrop.contains(node)) return null;
      const row = node.parentElement.closest('.sfl-line');
      const line = Array.prototype.indexOf.call(backdrop.children, row) + 1;
      const walker = document.createTreeWalker(row, NodeFilter.SHOW_TEXT);
      let col = offset;
      for (let t = walker.nextNode(); t && t !== node; t = walker.nextNode()) col += t.data.length;
      // The caret falls between characters: on the right half of a character
      // it is after it.
      const after = this.charBox(line, col);
      if (col > 0 && (!after || x < after.left)) col--;
      const box = this.charBox(line, col);
      const lineText = this.textarea.value.split('\n')[line - 1] || '';
      if (!box || col >= lineText.length || x < box.left || x > box.right || y < box.top || y > box.bottom) return null;
      return { line, col, box };
    }

    // Place a floating box under `box` (a character's), or above it when there
    // is no room below, within the window.
    place(node, box) {
      node.hidden = false;
      const area = this.area.getBoundingClientRect();
      const height = node.offsetHeight;
      const below = box.bottom + 4 + height <= window.innerHeight || box.top - 4 - height < 0;
      const top = below ? box.bottom + 4 : box.top - 4 - height;
      const left = Math.max(8, Math.min(box.left, window.innerWidth - node.offsetWidth - 8));
      node.style.top = (top - area.top) + 'px';
      node.style.left = (left - area.left) + 'px';
    }

    // ── Hover ──

    onMouseMove(x, y) {
      if (this.hoverFrame) return;
      this.hoverFrame = requestAnimationFrame(() => {
        this.hoverFrame = null;
        const hit = this.hitTest(x, y);
        const key = hit ? hit.line + ':' + hit.col : null;
        if (key === this.hoverKey) return;
        this.hoverKey = key;
        clearTimeout(this.hoverTimer);
        if (!hit) { this.leaveHover(); return; }
        clearTimeout(this.hideTimer);
        // Still over what the tooltip describes.
        const r = this.hoverRange;
        if (r && !this.tooltip.hidden && hit.line === r.line && hit.col >= r.from && hit.col < r.to) return;
        this.hideTooltip();
        this.hoverTimer = setTimeout(() => this.showHover(hit), 350);
      });
    }

    leaveHover() {
      clearTimeout(this.hoverTimer);
      this.hoverKey = null;
      clearTimeout(this.hideTimer);
      this.hideTimer = setTimeout(() => this.hideTooltip(), 250);
    }

    hideTooltip() {
      this.tooltip.hidden = true;
      this.hoverRange = null;
    }

    // The tooltip for the character at `hit`: Lean's messages squiggled
    // there, then what Lean knows of the name or term there (its type and
    // docstring), as Lean's editors show on hover.
    async showHover(hit) {
      const key = hit.line + ':' + hit.col;
      const code = this.textarea.value;
      const lineText = code.split('\n')[hit.line - 1] || '';
      const messages = this.squiggles
        .filter((s) => s.line === hit.line && hit.col >= s.from && hit.col < s.to)
        .sort((a, b) => STRENGTH[b.kind] - STRENGTH[a.kind]);
      let hover = null;
      if (lean.state === 'ready' && lean.queries) {
        const answer = await lean.info(code, this.context(code), hit.line, leanColumn(lineText, hit.col));
        if (this.hoverKey !== key || code !== this.textarea.value || this.closed) return;
        hover = answer.info && answer.info.hover;
      }
      if (!messages.length && !hover) return;
      this.tooltip.replaceChildren(
        ...this.messageList(messages.map((s) => s.message), (m, offered) =>
          el('div', { class: 'sfl-tip-message sfl-tip-' + category(m) }, this.messageBody(m, offered))),
        ...(hover ? [el('div', { class: 'sfl-tip-hover' }, ...markdown(hover.text))] : []));
      this.hoverRange = hover && hover.pos.line === hover.endPos.line
        ? { line: hit.line, from: jsOffset(lineText, hover.pos.column), to: jsOffset(lineText, hover.endPos.column) }
        : { line: hit.line, from: hit.col, to: hit.col + 1 };
      this.place(this.tooltip, hit.box);
    }

    // ── Completion ──

    inComment(pos) {
      const text = this.textarea.value;
      const lineStart = text.lastIndexOf('\n', pos - 1) + 1;
      return text.slice(lineStart, pos).includes('--') ||
        text.slice(0, pos).lastIndexOf('/-') > text.slice(0, pos).lastIndexOf('-/');
    }

    // Show the completions Lean gave for the name being typed, narrowed to
    // what has been typed since, and ask Lean again after `delay` ms.
    updateCompletion(delay) {
      const pos = this.textarea.selectionStart;
      const name = nameBefore(this.textarea.value, pos);
      if (!name || (!name.segment && !name.token.endsWith('.')) || this.inComment(pos)) {
        this.closeCompletion();
        return;
      }
      if (this.completion && !this.completion.symbols) this.showCompletions();
      clearTimeout(this.completeTimer);
      this.completeTimer = setTimeout(() => this.requestCompletions(), delay);
    }

    async requestCompletions() {
      if (lean.state !== 'ready' || !lean.queries || this.closed) return;
      const code = this.textarea.value;
      const name = nameBefore(code, this.textarea.selectionStart);
      if (!name) return;
      const at = this.position(name.pos, code);
      const seq = ++this.completionSeq;
      this.completionPending = true;
      const answer = await lean.complete(code, this.context(code), at.line, at.column);
      if (seq !== this.completionSeq || this.closed) return;
      this.completionPending = false;
      const now = nameBefore(this.textarea.value, this.textarea.selectionStart);
      if (!now || now.start !== name.start) return;
      if (answer.result && code === this.textarea.value) this.setDiagnostics(describe(answer.result, code).own, code);
      const items = ((answer.completions && answer.completions.items) || []).map((item, index) => ({ ...item, index }));
      this.completion = { start: name.start, items, shown: [], selected: 0, typed: null };
      this.showCompletions();
    }

    showCompletions() {
      const c = this.completion;
      const name = nameBefore(this.textarea.value, this.textarea.selectionStart);
      if (!c || !name || name.start !== c.start) { this.closeCompletion(); return; }
      const typed = name.segment;
      const shown = c.items
        .map((item) => ({ item, score: matchScore(item.label, typed) }))
        .filter((r) => r.score >= 0)
        .sort((a, b) => (a.item.deprecated - b.item.deprecated) || (b.score - a.score) ||
          a.item.label.localeCompare(b.item.label))
        .slice(0, 100)
        .map((r) => r.item);
      if (!shown.length || (shown.length === 1 && shown[0].label === typed)) {
        this.popup.hidden = true;
        return;
      }
      if (typed !== c.typed) c.selected = 0;
      c.typed = typed;
      c.shown = shown;
      this.completionList.replaceChildren(...shown.map((item) => el('div', {
        class: 'sfl-complete-item' + (item.deprecated ? ' sfl-deprecated' : ''), role: 'option',
        onclick: () => this.acceptCompletion(item),
      },
      el('span', { class: 'sfl-kind' }, KINDS[item.kind] || ''),
      el('span', { class: 'sfl-label' }, ...labelPieces(item.label, typed)))));
      const start = this.position(c.start);
      const box = this.charBox(start.line, start.col) || this.charBox(start.line, Math.max(0, start.col - 1));
      if (box) this.place(this.popup, box);
      this.selectCompletion(c.selected);
    }

    selectCompletion(i) {
      const c = this.completion;
      if (!c || !c.shown.length) return;
      c.selected = (i + c.shown.length) % c.shown.length;
      [...this.completionList.children].forEach((row, j) => row.classList.toggle('sfl-selected', j === c.selected));
      this.completionList.children[c.selected].scrollIntoView({ block: 'nearest' });
      this.describeSelected();
    }

    // The selected completion's type and docstring, which Lean works out
    // only for the items a reader looks at.
    async describeSelected() {
      const c = this.completion;
      const item = c.shown[c.selected];
      if (c.symbols) {
        this.completionDetail.hidden = true;
        return;
      }
      if (item.about === undefined && !this.completionPending) {
        item.about = null;
        item.about = (await lean.resolve(item.index)).item || {};
      }
      if (this.completion !== c || c.shown[c.selected] !== item) return;
      const about = item.about || {};
      const doc = about.documentation && markdown(about.documentation).slice(0, 3);
      this.completionDetail.replaceChildren(
        ...(about.detail ? [el('pre', { class: 'sfl-complete-type' }, ...highlighted(item.label + ' : ' + about.detail))] : []),
        ...(doc || []));
      this.completionDetail.hidden = !about.detail && !doc;
    }

    acceptCompletion(item) {
      const c = this.completion;
      const pos = this.textarea.selectionStart;
      const name = nameBefore(this.textarea.value, pos);
      this.closeCompletion();
      if (!item || !c) return;
      if (c.symbols) {
        const { text, cursor } = symbolText(item.symbol);
        this.edit(text, { from: c.start, to: pos, caret: cursor });
      } else if (name) {
        this.edit(item.label, { from: name.start, to: name.pos });
      }
    }

    abbreviationTyped() {
      return /\\[^\s\\]*$/.test(this.textarea.value.slice(0, this.textarea.selectionStart));
    }

    // The symbols that the abbreviation being typed may stand for, listed as
    // completions are, so a reader need not know the names: `\` alone offers
    // the book's common symbols, `\le` those whose abbreviation starts so.
    showSymbols() {
      const pos = this.textarea.selectionStart;
      const m = /\\([^\s\\]*)$/.exec(this.textarea.value.slice(0, pos));
      clearTimeout(this.completeTimer);
      this.completionSeq++;
      if (!m) { this.closeCompletion(); return; }
      const typed = m[1];
      // What space would put in comes first, then the common symbols in their
      // order, then the rest, shortest first.
      const common = (k) => (COMMON_ABBREVIATIONS.includes(k) ? COMMON_ABBREVIATIONS.indexOf(k) : 1000);
      const rank = (k) => (k === typed ? -1 : common(k));
      const keys = (typed ? Object.keys(ABBREVIATIONS).filter((k) => k.startsWith(typed))
        : COMMON_ABBREVIATIONS.filter((k) => k in ABBREVIATIONS))
        .sort((a, b) => rank(a) - rank(b) || a.length - b.length || a.localeCompare(b))
        .slice(0, 60);
      const shown = keys.map((k) => ({ abbreviation: k, symbol: ABBREVIATIONS[k] }));
      const same = this.completion && this.completion.symbols && this.completion.typed === typed;
      this.completion = { symbols: true, start: pos - m[0].length, shown, typed, selected: same ? this.completion.selected : 0 };
      if (!shown.length) { this.popup.hidden = true; return; }
      this.completionList.replaceChildren(...shown.map((item) => el('div', {
        class: 'sfl-complete-item', role: 'option', onclick: () => this.acceptCompletion(item),
      },
      el('span', { class: 'sfl-kind sfl-symbol' }, symbolText(item.symbol).text),
      el('span', { class: 'sfl-label' }, '\\', ...labelPieces(item.abbreviation, typed)))));
      const start = this.position(this.completion.start);
      const box = this.charBox(start.line, start.col);
      if (box) this.place(this.popup, box);
      this.selectCompletion(this.completion.selected);
    }

    closeCompletion() {
      clearTimeout(this.completeTimer);
      this.completionSeq++;
      this.completionPending = false;
      this.completion = null;
      this.popup.hidden = true;
    }

    // ── Running ──

    showStatus() {
      // Once a check has reported, its verdict stays until the code changes.
      if (!this.reported) this.status.textContent = lean.state === 'ready' ? 'Lean is ready.' : lean.status;
      this.runButton.disabled = lean.state === 'failed';
    }

    async run() {
      if (this.running) return;
      this.running = true;
      this.runButton.disabled = true;
      const code = this.textarea.value;
      this.reported = false;
      this.status.textContent = lean.state === 'ready' ? 'Checking…' : (lean.status || 'Starting Lean…');
      const started = performance.now();
      const result = await lean.compile(code, this.context(code));
      this.reported = true;
      this.running = false;
      this.runButton.disabled = false;
      this.show(describe(result, code), code, performance.now() - started);
    }

    show({ own, context, error }, code, elapsed) {
      if (code === this.textarea.value) this.setDiagnostics(own, code);
      const items = this.messageItems(own.filter((m) => !m.isSilent && !isUnsolvedGoals(m)), true);
      if (context.length) {
        items.unshift(el('div', { class: 'sfl-message sfl-error' },
          el('pre', {}, `The book code before this ${this.exercise.block ? 'code' : 'exercise'} did not check, ` +
            'so this result cannot be trusted. ' +
            'Please report it. First problem:\n' + context[0].data)));
      }
      if (error) items.push(el('div', { class: 'sfl-message sfl-error' }, el('pre', {}, error)));
      this.messages.replaceChildren(...items);
      if (code === this.textarea.value) this.judge({ own, context, error }, code, ` (${(elapsed / 1000).toFixed(1)} s)`);
    }

    // Show a check's verdict.  An exercise's code that Lean accepts is saved
    // at once, so the exercises after this one build on it whether or not the
    // reader presses Run.  A later edit that breaks it keeps the saved version,
    // until Reset.
    judge(described, code, timing = '') {
      const { solved, text } = verdict(described, this.exercise.block);
      this.reported = true;
      this.status.textContent = text + timing;
      this.root.classList.toggle('sfl-solved', solved);
      if (solved && !this.exercise.block) save('solved:' + this.key, code);
    }

    goTo(line, col) {
      const lines = this.textarea.value.split('\n');
      let offset = 0;
      for (let i = 0; i < line - 1 && i < lines.length; i++) offset += lines[i].length + 1;
      offset += col || 0;
      this.textarea.focus();
      this.textarea.setSelectionRange(offset, offset);
      this.onCursorMove();
    }
  }

  // ── The toolbar on each exercise and block ────────────────────────────────

  function closeMenus() {
    for (const list of document.querySelectorAll('.sfl-menu-list')) list.hidden = true;
  }

  function menu(items) {
    const list = el('div', { class: 'sfl-menu-list', role: 'menu', hidden: '' });
    const toggle = el('button', {
      class: 'sfl-menu-button', type: 'button', 'aria-haspopup': 'true', 'aria-label': 'More options',
      onclick: (e) => {
        e.stopPropagation();
        const wasHidden = list.hidden;
        closeMenus();
        list.hidden = !wasHidden;
        if (list.hidden) return;
        // The list is placed on the window, under the button: the book clips
        // its code blocks, and a block's menu would be cut off at its edge.
        const r = toggle.getBoundingClientRect();
        list.style.top = r.bottom + 2 + 'px';
        list.style.right = document.documentElement.clientWidth - r.right + 'px';
      },
    }, '⋮');
    for (const item of items) {
      if (!item) continue;
      const attrs = { class: 'sfl-menu-item', role: 'menuitem' };
      const node = item.href
        ? el('a', { ...attrs, href: item.href, target: '_blank', rel: 'noopener' }, item.label)
        : el('button', { ...attrs, type: 'button', onclick: () => { list.hidden = true; item.action(); } }, item.label);
      if (item.href && item.onopen) node.addEventListener('click', item.onopen);
      list.append(node);
    }
    return el('span', { class: 'sfl-menu' }, toggle, list);
  }

  function download(name, text) {
    const url = URL.createObjectURL(new Blob([text], { type: 'text/plain' }));
    const a = el('a', { href: url, download: name });
    document.body.append(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }

  // An exercise's or a block's tools: a button that opens and closes the
  // editor, or a link to the playground where Lean cannot run here, and the
  // "⋮" menu.  `place` opens an editor on the page and returns it; `onClose`
  // runs once it is closed.
  function toolbar(data, exercise, runsHere, label, place, onClose = () => {}) {
    let editor = null;
    const reopen = exercise.block ? 'block:' + exercise.index : exercise.name;
    const openPlayground = (e) => {
      // Built on click: the URL holds the whole file, so it is not worth
      // building for every exercise on page load.
      e.currentTarget.href = playgroundUrl(data, exercise);
    };
    const tryButton = runsHere
      ? el('button', {
        class: 'sfl-try', type: 'button',
        onclick: async () => {
          if (editor) {
            editor.close();
            editor = null;
            tryButton.textContent = label;
            onClose();
            return;
          }
          if (!(await ensureIsolated(reopen))) {
            tryButton.replaceWith(playgroundLink());
            return;
          }
          lean.start(data);
          editor = place();
          tryButton.textContent = 'Close editor';
        },
      }, label)
      : null;
    function playgroundLink() {
      const a = el('a', { class: 'sfl-try', href: PLAYGROUND, target: '_blank', rel: 'noopener' },
        'Open in the Lean playground ↗');
      a.addEventListener('click', openPlayground);
      return a;
    }
    const source = sourceUrl(data, exercise);
    // In a block's corner the playground link would cover the code, and the
    // menu has it.
    const node = el('span', { class: 'sfl-toolbar' },
      tryButton || (exercise.block ? null : playgroundLink()),
      menu([
        { label: 'Open in the Lean playground ↗', href: PLAYGROUND, onopen: openPlayground },
        { label: 'Download as a .lean file', action: () => download(`${data.chapter}_${exercise.name}.lean`, playgroundFile(data, exercise)) },
        source && { label: 'View source on GitHub ↗', href: source },
        runsHere && { label: 'Reset to the original code', action: () => editor && editor.reset() },
      ]));
    return { node, reopen, open: () => tryButton && tryButton.click() };
  }

  function attach(data, exercise, box, runsHere) {
    const head = box.querySelector('.exercise-header');
    if (!head || head.querySelector('.sfl-toolbar')) return null;
    const tools = toolbar(data, exercise, runsHere, 'Try it here', () => {
      const editor = new ExerciseEditor(data, exercise, box);
      editor.open();
      return editor;
    });
    head.append(tools.node);
    return tools;
  }

  // A block's tools sit in its top right corner, shown while the pointer is
  // on the block or they have the focus.  The block is hidden while the
  // editor is open, so they move to the editor's bar.  So is the output Verso
  // shows under the block, which is about the book's code.
  function attachBlock(data, block, node, runsHere) {
    const hidden = [node];
    for (let next = node.nextElementSibling; next && next.matches('.lean-output'); next = next.nextElementSibling) {
      hidden.push(next);
    }
    const tools = toolbar(data, block, runsHere, 'Edit', () => {
      const editor = new ExerciseEditor(data, block, node.parentElement, hidden);
      editor.open();
      editor.bar.append(tools.node);
      return editor;
    }, () => node.append(tools.node));
    tools.node.classList.add('sfl-block-tools');
    node.classList.add('sfl-editable');
    node.append(tools.node);
    return tools;
  }

  // A code block's text as the reader sees it: Verso keeps hover contents
  // and the goal after each tactic inside the block.  scripts/web_exercises.py
  // reads the page the same way to match each block with its data.
  function blockText(node) {
    const copy = node.cloneNode(true);
    for (const inner of copy.querySelectorAll('.hover-container, .tactic-state, .sfl-block-tools')) inner.remove();
    return copy.textContent.replace(/^\n+|\n+$/g, '');
  }

  async function main() {
    const boxes = [...document.querySelectorAll('.exercise')];
    const blocks = document.querySelectorAll('code.hl.lean.block');
    if (!boxes.length && !blocks.length) return;
    const chapter = chapterOfPage();
    let data;
    try {
      const response = await fetch(new URL(`data/${chapter}.json`, here));
      if (!response.ok) return;
      data = await response.json();
    } catch (e) {
      return;
    }
    const byName = new Map(data.exercises.map((e) => [e.name, e]));
    const runsHere = canRunLean();
    const openers = new Map();
    for (const box of boxes) {
      const label = box.querySelector('.exercise-name');
      const name = label && label.textContent.trim().replace(/^\(|\)$/g, '');
      const exercise = byName.get(name);
      const tools = exercise && attach(data, exercise, box, runsHere);
      if (tools) openers.set(tools.reopen, tools.open);
    }
    for (const block of data.blocks ?? []) {
      // The page and its data come from one build, so a block whose text is
      // not the data's is left as the book shows it.
      const node = blocks[block.index];
      if (!node || blockText(node) + '\n' !== block.code) continue;
      const tools = attachBlock(data, { ...block, block: true }, node, runsHere);
      openers.set(tools.reopen, tools.open);
    }
    document.addEventListener('click', closeMenus);
    // A menu is placed on the window, so it would stay put as the page moves.
    document.addEventListener('scroll', closeMenus, { capture: true, passive: true });
    // Back from the one-time reload that turned on cross-origin isolation.
    const reopen = sessionStorage.getItem(STORE + 'reopen');
    if (reopen && openers.has(reopen)) {
      sessionStorage.removeItem(STORE + 'reopen');
      openers.get(reopen)();
    }
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', main);
  else main();
})();
